// QueueAPM.cpp : Defines the entry point for the DLL application.//#include "stdafx.h"#define __MAIN_FILE__#include "Queue.h"#include "QueueAPM.h"#include "Function.h"#include "MnemoWnd.h"//SQueue BuildQueue( CQueueWnd* wnd, const char* szPath, const char* szName )  {  //  SQueue q;  memset( &q, 0, sizeof(q) );  q.m_pPipe  = wnd->mQueue.m_pPipe ;  q.m_pSocket  = wnd->mQueue.m_pSocket ;  q.setShift = wnd->mQueue.setShift;  q.setScale = wnd->mQueue.setScale;  q.hWnd     = wnd->m_hWnd;  if ( szName )  lstrcpy( q.szName, szName );  //  CLang::ms_bAddQueue = true;  char* ptr = ::FileToBuff( szPath );  if ( ptr )    {    CLang::ms_nStack = 0;    ::ParserQueue( q, ptr, wnd->mLogic );    CLang::ms_nStack = 0;    ::BuffFree(ptr);    }  CLang::ms_bAddQueue = true;  return q;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~inline void DeleteGDI( HBITMAP& obj )  {  if ( obj )    ::DeleteObject( obj );  obj = NULL;  }void DeleteQueue(SQueue& q,SBuffer& Buffer);#define DefineDelete SQueue& q,LPBYTE& szQueueint DeleteNull(DefineDelete)  {  return SkipQueue(szQueue);  }int DeleteMacros(DefineDelete)  {  QueueM(Queue_Macros);  if ( p->nParams > 0 )    DeleteQueue(q,p->Buffer);  return 1;  }//int DeleteLibrary(DefineDelete)  {  QueueM(Queue_Library);  if ( p->clear != NULL )    (*p->clear)( q, p );  return 1;  }//typedef int (*LPFuncDelete)(DefineDelete);static  LPFuncDelete gs_funcDelete[TYPE_UNKNOWN+1];static void Init(SQueue& q)  {  for ( int n = 0; n < TYPE_UNKNOWN+1; n++ )    gs_funcDelete[n] = DeleteNull;  gs_funcDelete[TYPE_MACROS  ] = DeleteMacros;  gs_funcDelete[TYPE_LIBRARY ] = DeleteLibrary;  }////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void DeleteQueue(SQueue& q,SBuffer& Buffer)  {  INIT  LPBYTE szQueue = Buffer.szQueue;  if ( szQueue )    {    while ( gs_funcDelete[*szQueue](q,szQueue) );    ::BuffFree(Buffer.szQueue);    Buffer.szQueue = NULL;    Buffer.nPtr = 0;    Buffer.dwQueueMax = 0;    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void FreeQueue (SQueue& q)  {  //  DeleteQueue(q,q.Stat);  DeleteQueue(q,q.Dyna);  //  for ( int m = 0; m < q.cntFunc; m++ )    ::BuffFree( q.arrFunc[m].buff );  ::BuffFree( q.arrFunc );  //  DeleteGDI( q.bmpStat );  DeleteGDI( q.bmpFull );  //  for ( int n = 0; n < q.cntPribor; n++ )  ::DeletePribor( q.arrPribor[n] );  ::BuffFree( q.arrPribor );  q.cntPribor = 0;  q.maxPribor = 0;  //  }